select 1 from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL
where
B_TRADE_ID = #{tradeId}
and IS_CANCEL = #{yes_no}
and PS = #{ps}
and TRADE_STATUS = #{trade_status}
)

