select psp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, PSP.SEC_ACCT_ID, psp.AMOUNT bconShareAmt from PTL_SEC_POSITION psp inner join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID inner join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = psp.PORTFOLIO_ID where nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' and psp.CDATE = #{conversionTime,jdbcType=DATE}
and psp.AMOUNT >0 and fp.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
and psp.HODING_TYPE = #{POSITION_TYPE03}
and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' order by AMOUNT

